// Strong controls; native/Wasm use identical Rust source and fixed ABI.
#[no_mangle]pub extern "C" fn bench_alloc(n:usize)->*mut u32{let mut v=vec![0;n];let p=v.as_mut_ptr();std::mem::forget(v);p}
#[no_mangle]pub unsafe extern "C" fn bench_free(p:*mut u32,n:usize){drop(Vec::from_raw_parts(p,n,n));}
#[no_mangle]pub unsafe extern "C" fn bench_eval(case:u32,xp:*const u32,xn:usize,yp:*const u32,yn:usize,seed:u32,k:u32,out:*mut u32)->usize{let xs=std::slice::from_raw_parts(xp,xn);let ys=std::slice::from_raw_parts(yp,yn);match case{
0=>{let values=xs;let stage0:Vec<u32>=values.iter().copied().filter(|&x|x<seed).collect();let values=&stage0[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
1=>{let values=xs;let stage0:Vec<u32>=values.iter().map(|&x|((x).wrapping_mul(3u32)).wrapping_add(k)).collect();let values=&stage0[..];let stage1:Vec<u32>=values.iter().copied().filter(|&x|x<seed).collect();let values=&stage1[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
2=>{let values=xs;let stage0:Vec<u32>=values.iter().copied().filter(|&x|x<seed).collect();let values=&stage0[..];let stage1:Vec<u32>=values.iter().map(|&x|((x).wrapping_mul(3u32)).wrapping_add(k)).collect();let values=&stage1[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
3=>{let left:Vec<u32>=xs.iter().map(|&x|(if (x<seed){(seed).wrapping_sub(x)}else{(x).wrapping_sub(seed)})).collect();let mut a:u32=0;for &x in &left{a=a.wrapping_add(x);}drop(left);let right:Vec<u32>=xs.iter().map(|&x|((x).wrapping_add(seed)).wrapping_mul(k)).collect();let mut b:u32=0;for &x in &right{b=b.wrapping_add(x);}*out=a.wrapping_add(b);1},
4=>{let left:Vec<u32>=xs.iter().map(|&x|(if (x<seed){(seed).wrapping_sub(x)}else{(x).wrapping_sub(seed)})).collect();let mut a:u32=0;for &x in &left{a=a.wrapping_add(x);}drop(left);let right:Vec<u32>=xs.iter().map(|&x|((x).wrapping_add(seed)).wrapping_mul(k)).collect();let mut b:u32=0;for &x in &right{b=b.wrapping_add(x);}*out=a.wrapping_sub(b);1},
5=>{let left:Vec<u32>=xs.iter().map(|&x|(if (x<seed){(seed).wrapping_sub(x)}else{(x).wrapping_sub(seed)})).collect();let mut a:u32=0;for &x in &left{a=a.wrapping_add(x);}drop(left);let right:Vec<u32>=xs.iter().map(|&x|((x).wrapping_add(seed)).wrapping_mul(k)).collect();let mut b:u32=0;for &x in &right{b=b.wrapping_add(x);}*out=a.wrapping_mul(k).wrapping_add(b.wrapping_mul(seed));1},
6=>{let values=xs;let stage0:Vec<u32>=values.iter().copied().filter(|&x|x>k).collect();let values=&stage0[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
7=>{let values=xs;let stage0:Vec<u32>=values.iter().map(|&x|(if (x<seed){(seed).wrapping_sub(x)}else{(x).wrapping_sub(seed)})).collect();let values=&stage0[..];let stage1:Vec<u32>=values.iter().copied().filter(|&x|x>k).collect();let values=&stage1[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
8=>{let values=xs;let stage0:Vec<u32>=values.iter().copied().filter(|&x|x>k).collect();let values=&stage0[..];let stage1:Vec<u32>=values.iter().map(|&x|(if (x<seed){(seed).wrapping_sub(x)}else{(x).wrapping_sub(seed)})).collect();let values=&stage1[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
9=>{let left:Vec<u32>=xs.iter().map(|&x|(if (x>k){(x).wrapping_sub(k)}else{(k).wrapping_sub(x)})).collect();let mut a:u32=0;for &x in &left{a=a.wrapping_add(x);}drop(left);let right:Vec<u32>=xs.iter().map(|&x|((x).wrapping_mul(x)).wrapping_add(seed)).collect();let mut b:u32=0;for &x in &right{b=b.wrapping_add(x);}*out=a.wrapping_add(b);1},
10=>{let left:Vec<u32>=xs.iter().map(|&x|(if (x>k){(x).wrapping_sub(k)}else{(k).wrapping_sub(x)})).collect();let mut a:u32=0;for &x in &left{a=a.wrapping_add(x);}drop(left);let right:Vec<u32>=xs.iter().map(|&x|((x).wrapping_mul(x)).wrapping_add(seed)).collect();let mut b:u32=0;for &x in &right{b=b.wrapping_add(x);}*out=a.wrapping_sub(b);1},
11=>{let left:Vec<u32>=xs.iter().map(|&x|(if (x>k){(x).wrapping_sub(k)}else{(k).wrapping_sub(x)})).collect();let mut a:u32=0;for &x in &left{a=a.wrapping_add(x);}drop(left);let right:Vec<u32>=xs.iter().map(|&x|((x).wrapping_mul(x)).wrapping_add(seed)).collect();let mut b:u32=0;for &x in &right{b=b.wrapping_add(x);}*out=a.wrapping_mul(k).wrapping_add(b.wrapping_mul(seed));1},
12=>{let values=xs;let stage0:Vec<u32>=values.iter().map(|&x|((x).wrapping_mul(3u32)).wrapping_add(k)).collect();let values=&stage0[..];let mut a:u32=seed;for &x in values.iter().rev(){a=x.wrapping_add(a.wrapping_mul(k));}*out=a;1},
13=>{let values=xs;let stage0:Vec<u32>=values.iter().copied().filter(|&x|x<seed).collect();let values=&stage0[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
14=>{let values=xs;let stage0:Vec<u32>=values.iter().map(|&x|((x).wrapping_mul(3u32)).wrapping_add(k)).collect();let values=&stage0[..];let stage1:Vec<u32>=values.iter().copied().filter(|&x|x<seed).collect();let values=&stage1[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
15=>{let values=xs;let stage0:Vec<u32>=values.iter().map(|&x|(if (x<seed){(seed).wrapping_sub(x)}else{(x).wrapping_sub(seed)})).collect();let values=&stage0[..];let mut a:u32=0;for &x in values.iter(){a=a.wrapping_add(x);}*out=a;1},
16=>{let values=xs;let stage0:Vec<u32>=values.iter().copied().filter(|&x|x>seed).collect();let values=&stage0[..];let mut a:u32=seed;for &x in values.iter().rev(){a=x.wrapping_add(a.wrapping_mul(k));}*out=a;1},
17=>{let values=xs;let stage0:Vec<u32>=values.iter().map(|&x|(if (x<seed){(x).wrapping_add(k)}else{(x).wrapping_sub(k)})).collect();let values=&stage0[..];let stage1:Vec<u32>=values.iter().copied().filter(|&x|x>seed).collect();let values=&stage1[..];let mut a:u32=seed;for &x in values.iter().rev(){a=x.wrapping_add(a.wrapping_mul(k));}*out=a;1},
_=>panic!("unknown case")}}
